  }
}];

let textoCompleto = $json.resposta_limpa || $json.output || $json.text || "";

if (!textoCompleto || !textoCompleto.trim()) {
  textoCompleto = "Agendamento confirmado com sucesso! 🎉 Te esperamos no Studio V.";
}

// 1. Normaliza quebras de linha
textoCompleto = textoCompleto.replace(/\r\n/g, '\n').trim();

// 2. Colapsa linhas em branco duplas entre cabeçalhos de lista e itens (: \n\n *)
textoCompleto = textoCompleto.replace(/(:\s*)\n\s*\n+/g, '$1\n');

// 3. Colapsa linhas em branco duplas entre itens de lista (*, -, •, números, horários)
// Isso impede que cada serviço ou horário vire uma mensagem separada no WhatsApp!
textoCompleto = textoCompleto.replace(/\n\s*\n+(?=[ \t]*[*•\-\d])/g, '\n');
textoCompleto = textoCompleto.replace(/\n\s*\n+(?=[ \t]*\d{1,2}:\d{2})/g, '\n');

// 4. Divide os blocos apenas por quebras duplas reais de parágrafo
let blocos = textoCompleto
  .split(/\n\s*\n+/)
  .map(msg => msg.trim())
  .filter(msg => msg.length > 0);

// 5. Limite de segurança: no máximo 2 a 3 mensagens por resposta para não picotar no WhatsApp
if (blocos.length > 3) {
  const primeiros = blocos.slice(0, 2);
  const restante = blocos.slice(2).join('\n\n');
  blocos = [...primeiros, restante];
}

return blocos.map(msg => ({ json: { mensagem_fragmentada: msg } }));

