const output = $json.output || $json.text || "";

// Extrai o bloco <ESTADO>...</ESTADO>
const estadoMatch = output.match(/<ESTADO>([\s\S]*?)<\/ESTADO>/);
let estado = {
  acao: "conversa",
  agendamentos: [],
  confirmado_pelo_cliente: false
};

if (estadoMatch) {
  try {
    estado = JSON.parse(estadoMatch[1].trim());
  } catch(e) {
    estado.confirmado_pelo_cliente = false;
  }
}

// Respeita estritamente o booleano emitido pela IA no JSON
estado.confirmado_pelo_cliente = estado.confirmado_pelo_cliente === true;

// Remove o bloco <ESTADO> da resposta visível ao cliente
let resposta = output.replace(/<ESTADO>[\s\S]*?<\/ESTADO>/, '').trim();

// FILTRO INTELIGENTE E SEGURO (COM ÂNCORAS DE AGENDAMENTO)
const linhas = resposta.split('\n');
const temAgendamentoNoTexto = linhas.some(l => {
  const txt = l.toLowerCase();
  return txt.includes('horário') || txt.includes('horario') || txt.includes('disponív') || txt.includes('agend') || txt.includes('confirm');
});

if (temAgendamentoNoTexto) {
  const linhasValidas = linhas.filter(linha => {
    const l = linha.toLowerCase().trim();
    if (!l) return false;

    // ÂNCORA DE SEGURANÇA: Se a frase tem hora (15:00), data (15/09) ou termos de agendamento, ELA É 100% PRESERVADA!
    const eFraseLegitimaAgendamento = /\d{1,2}:\d{2}/.test(l) || 
                                       /\d{1,2}\/\d{1,2}/.test(l) || 
                                       l.includes('agend') || 
                                       l.includes('disponív') || 
                                       l.includes('confirm') || 
                                       l.includes('horário') || 
                                       l.includes('horario') ||
                                       l.includes('serviço') ||
                                       l.includes('servico');

    if (eFraseLegitimaAgendamento) {
      return true; // NUNCA deleta frases reais do salão!
    }

    // Se a frase NÃO tem nenhum elemento de agendamento:
    // Se for conta matemática (ex: "159 + 159 é 318") ou frase solta fora do escopo, descarta!
    if (/\d+\s*[\+\-\*\/\=]\s*\d+/.test(l)) return false;
    if (l.includes('escopo') || l.includes('não posso responder') || l.includes('não fazem parte')) return false;

    return true;
  });

  if (linhasValidas.length > 0) {
    resposta = linhasValidas.join('\n\n').trim();
  }
}

return [{
  json: {
    ...$json,
    resposta_limpa: resposta,
    estado: estado
  }
}];

const estado = $json.estado || {};
const outputText = $json.resposta_limpa || $json.output || '';
const triagem = $('Triagem variáveis').first().json;
const estab = $('formatar dados estabelecimento').first().json;

// Carrega os serviços do banco para consulta de duração oficial
let servicosBanco = [];
try {
  servicosBanco = $('buscar serviços').all().map(item => item.json);
} catch(err) {}

let lista = [];

// 1. Array 'agendamentos' no JSON do estado
if (Array.isArray(estado.agendamentos) && estado.agendamentos.length > 0) {
  lista = estado.agendamentos.filter(a => a && (a.servico || a.data_hora_inicio || a.horario));
}

// 2. Objeto único na raiz do JSON do estado
if (lista.length === 0 && (estado.servico || estado.data_hora_inicio || estado.horario)) {
  lista = [{
    servico: estado.servico,
    duracao_minutos: estado.duracao_minutos,
    data: estado.data,
    horario: estado.horario,
    data_hora_inicio: estado.data_hora_inicio,
    nome_cliente: estado.nome_cliente
  }];
}

// 3. Fallback por Texto se a IA omitiu o JSON ao confirmar
if (lista.length === 0 && estado.confirmado_pelo_cliente) {
  for (const s of servicosBanco) {
    const regexNome = new RegExp(s.nome.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
    if (regexNome.test(outputText)) {
      const dateMatch = outputText.match(/(\d{2}\/\d{2}\/\d{4}|\d{4}-\d{2}-\d{2})/);
      const timeMatch = outputText.match(/(\d{1,2}:\d{2})/);
      let dataIso = '';
      if (dateMatch && timeMatch) {
        let dStr = dateMatch[1];
        if (dStr.includes('/')) {
          const [d, m, y] = dStr.split('/');
          dStr = `${y}-${m}-${d}`;
        }
        const hStr = timeMatch[1].padStart(5, '0');
        dataIso = `${dStr}T${hStr}:00-03:00`;
      }
      if (dataIso) {
        lista.push({
          servico: s.nome,
          duracao_minutos: s.duracao_minutos,
          data_hora_inicio: dataIso,
          nome_cliente: estado.nome_cliente || triagem.nome_pessoa
        });
      }
    }
  }
}

return lista.map(item => {
  const nomeProc = (item.servico || estado.servico || '').trim();

  // Duração oficial pelo banco de dados Postgres
  let duracao = Number(item.duracao_minutos || estado.duracao_minutos || 0);
  if (!duracao || isNaN(duracao)) {
    const servEncontrado = servicosBanco.find(s => 
      s.nome.toLowerCase().includes(nomeProc.toLowerCase()) || 
      nomeProc.toLowerCase().includes(s.nome.toLowerCase())
    );
    duracao = servEncontrado ? Number(servEncontrado.duracao_minutos) : 30;
  }
  if (!duracao || isNaN(duracao)) duracao = 30;

  // Formatação ISO 8601 determinística em código
  let dhInicio = String(item.data_hora_inicio || estado.data_hora_inicio || '').trim();
  if (!dhInicio && (item.data || estado.data) && (item.horario || estado.horario)) {
    let dStr = String(item.data || estado.data).trim();
    if (dStr.includes('/')) {
      const [d, m, y] = dStr.split('/');
      dStr = `${y}-${m.padStart(2,'0')}-${d.padStart(2,'0')}`;
    }
    let hStr = String(item.horario || estado.horario).trim();
    if (hStr.length === 4 && !hStr.includes(':')) hStr = `${hStr.substring(0,2)}:${hStr.substring(2,4)}`;
    hStr = hStr.padStart(5, '0');
    dhInicio = `${dStr}T${hStr}:00-03:00`;
  }

  return {
    json: {
      nome_cliente: item.nome_cliente || estado.nome_cliente || triagem.nome_pessoa || 'Cliente',
      procedimento: nomeProc,
      data_hora_inicio: dhInicio,
      duracao_minutos: duracao,
      telefone_cliente: triagem.numero,
      turno_manha_inicio: estab.turno_manha_inicio,
      turno_manha_fim: estab.turno_manha_fim,
      turno_tarde_inicio: estab.turno_tarde_inicio,
      turno_tarde_fim: estab.turno_tarde_fim,
      horarios_por_dia: estab.horarios_por_dia,
      datas_bloqueadas: estab.datas_bloqueadas,
      instancia: triagem.instancia,
      google_calendar_id: estab.google_calendar_id,
      google_access_token: estab.google_access_token,
      google_refresh_token: estab.google_refresh_token
    }
  };
});

// Coleta o resultado de cada criação (sucesso ou falha) mantendo a execução do loop ativa
const item = $input.first().json;
const loopInput = $('Loop Agendamentos').item.json;

return [{
  json: {
    sucesso: item.sucesso === true || (item.id !== undefined && item.id !== null),
    procedimento: item.procedimento || loopInput.procedimento,
    data_hora_inicio: item.data_hora_inicio || loopInput.data_hora_inicio,
    mensagem_erro: item.mensagem_para_agente || item.mensagem || 'Horário indisponível ou limite atingido.'
  }
}];

const resultados = $input.all().map(item => item.json);
const respostaOriginal = $('Extrai estado do agente').first().json.resposta_limpa;

const comSucesso = resultados.filter(r => r.sucesso);
const comFalha = resultados.filter(r => !r.sucesso);

let mensagemFinal = "";

if (comFalha.length === 0) {
  // Todos os agendamentos foram criados com sucesso!
  if (respostaOriginal && respostaOriginal.trim().length > 0) {
    mensagemFinal = respostaOriginal;
  } else {
    // Se a IA gerou apenas o bloco <ESTADO> sem texto falado, constrói a mensagem de confirmação
    const listaSucessoStr = comSucesso.map(s => {
      let horaStr = '';
      if (typeof s.data_hora_inicio === 'string' && s.data_hora_inicio.includes('T')) {
        horaStr = s.data_hora_inicio.split('T')[1].substring(0, 5);
      } else {
        const d = new Date(s.data_hora_inicio);
        horaStr = isNaN(d.getTime()) ? s.data_hora_inicio : d.toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' });
      }
      return `• ${s.procedimento} às ${horaStr}`;
    }).join('\n');

    mensagemFinal = `Agendamento confirmado com sucesso! 🎉\n\n${listaSucessoStr}\n\nTe esperamos no Studio V! Se precisar alterar ou cancelar, estou à disposição.`;
  }
} else if (comSucesso.length > 0 && comFalha.length > 0) {
  const listaSucessoStr = comSucesso.map(s => {
    let horaStr = '';
    if (typeof s.data_hora_inicio === 'string' && s.data_hora_inicio.includes('T')) {
      horaStr = s.data_hora_inicio.split('T')[1].substring(0, 5);
    } else {
      const d = new Date(s.data_hora_inicio);
      horaStr = isNaN(d.getTime()) ? s.data_hora_inicio : d.toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' });
    }
    return `• ${s.procedimento} às ${horaStr}`;
  }).join('\n');

  const motivoErro = comFalha[0].mensagem_erro;
  mensagemFinal = `Consegui agendar com sucesso o(s) seguinte(s) horário(s):\n${listaSucessoStr}\n\nPorém, não foi possível agendar o outro horário solicitado pelo seguinte motivo:\n${motivoErro}`;
} else {
  const motivoErro = comFalha[0].mensagem_erro || '';
  if (motivoErro.includes('ausente') || motivoErro.includes('inválid') || motivoErro.includes('obrigat')) {
    mensagemFinal = respostaOriginal || "Para agendar, por favor escolha um serviço e um horário válido.";
  } else {
    mensagemFinal = `Não foi possível registrar o agendamento:\n${motivoErro}\n\nPor favor, escolha outro horário ou verifique seus agendamentos ativos.`;
  }
}

return [{
  json: {
    ...$json,
    resposta_limpa: mensagemFinal,
    sucesso: comSucesso.length > 0
  }
}];

